import urllib.request
for url in ['https://deps.buildcache.dev/setup-guide','https://deps.buildcache.dev/bootstrap.sh']:
 try:
  with urllib.request.urlopen(url,timeout=10) as r:
   print(url, r.status, r.geturl(), r.headers.get('content-type'))
   print(r.read(500).decode('utf8','replace'))
 except Exception as e: print(url,type(e).__name__,e)
